import numpy as np

_MOVES = {
    1: (-4, 0),
    2: (4, 0),
    3: (0, -4),
    4: (0, 4),
}

_TOP_PATTERN = [2, 2, 2, 3, 2, 2, 2, 2]
_TOP_CYCLE = sum(_TOP_PATTERN)
_TOP_LEN_BY_MOD = {}
_s = 0
for _l in _TOP_PATTERN:
    _TOP_LEN_BY_MOD[_s % _TOP_CYCLE] = _l
    _s += _l


def engine(grid, action, data):
    g = np.array(grid, copy=True)
    H, W = g.shape

    move = _MOVES.get(action)
    if move is not None and H > 0 and W > 0:
        dr, dc = move
        old_mask = (g == 9)
        if old_mask.any():
            ys, xs = np.nonzero(old_mask)
            ny = ys + dr
            nx = xs + dc

            if ny.min() >= 1 and ny.max() < H and nx.min() >= 0 and nx.max() < W:
                new_mask = np.zeros_like(g, dtype=bool)
                new_mask[ny, nx] = True

                entered = new_mask & ~old_mask
                ok = True
                if entered.any():
                    vals = g[entered]
                    if not np.all((vals == 12) | (vals == 0)):
                        ok = False

                if ok:
                    g[old_mask] = 12
                    g[new_mask] = 9

    if H > 0 and W > 0:
        b = 0
        while b < W and g[0, W - 1 - b] == 0:
            b += 1

        if b < W:
            take_len = _TOP_LEN_BY_MOD.get(b % _TOP_CYCLE, 2)
            start_col = W - b
            max_take = min(take_len, start_col)
            take = 0

            for i in range(max_take):
                col = start_col - 1 - i
                if g[0, col] == 14:
                    take = i + 1
                else:
                    break

            if take > 0:
                g[0, start_col - take:start_col] = 0

    return g


def is_level_complete(grid):
    if grid.size == 0 or grid.shape[0] == 0:
        return False
    return not np.any(grid[0] == 14)

import numpy as np

_DIRS = ((1, 0), (-1, 0), (0, 1), (0, -1))


def _floor_bbox(grid):
    """Bounding box of the large color-4 room/floor."""
    ys, xs = np.nonzero(grid == 4)
    if ys.size == 0:
        return None
    return (int(ys.min()), int(xs.min()), int(ys.max()), int(xs.max()))


def _component_at(grid, r, c):
    """4-connected same-color component containing (r, c)."""
    h, w = grid.shape
    color = int(grid[r, c])
    stack = [(r, c)]
    seen = {(r, c)}
    coords = []
    min_r = max_r = r
    min_c = max_c = c

    while stack:
        rr, cc = stack.pop()
        coords.append((rr, cc))

        if rr < min_r:
            min_r = rr
        if rr > max_r:
            max_r = rr
        if cc < min_c:
            min_c = cc
        if cc > max_c:
            max_c = cc

        for dr, dc in _DIRS:
            nr = rr + dr
            nc = cc + dc
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen:
                if int(grid[nr, nc]) == color:
                    seen.add((nr, nc))
                    stack.append((nr, nc))

    return coords, (min_r, min_c, max_r, max_c)


def _add_progress(out):
    """Add one two-cell progress unit to the bottom bar from right to left."""
    h, w = out.shape
    if h == 0 or w < 2:
        return out

    row = out[-1]
    trailing_11 = 0
    while trailing_11 < w and int(row[w - 1 - trailing_11]) == 11:
        trailing_11 += 1

    filled_pairs = trailing_11 // 2
    if filled_pairs * 2 >= w:
        return out

    i = w - 1 - 2 * filled_pairs
    j = i - 1
    if j >= 0:
        out[-1, j:i + 1] = 11

    return out


def engine(grid, action, data):
    out = np.array(grid, copy=True)

    # Only observed interactive action is ACTION6 (click).
    if action != 6 or data is None:
        return out

    try:
        x = int(data["x"])
        y = int(data["y"])
    except Exception:
        return out

    h, w = out.shape
    if not (0 <= x < w and 0 <= y < h):
        return out

    # Collectible objects are color-9 components inside the color-4 room.
    if int(out[y, x]) != 9:
        return out

    fb = _floor_bbox(out)
    if fb is None:
        return out

    fy0, fx0, fy1, fx1 = fb
    coords, bbox = _component_at(out, y, x)
    cy0, cx0, cy1, cx1 = bbox

    # The whole clicked object must lie within the room bounding box.
    if cy0 >= fy0 and cy1 <= fy1 and cx0 >= fx0 and cx1 <= fx1:
        for rr, cc in coords:
            out[rr, cc] = 8
        _add_progress(out)

    return out


def is_level_complete(grid):
    g = np.asarray(grid)
    fb = _floor_bbox(g)
    if fb is None:
        return False

    fy0, fx0, fy1, fx1 = fb
    h, w = g.shape

    mask = (g == 9)
    visited = np.zeros((h, w), dtype=bool)

    # Any fully-contained color-9 component still means uncollected items remain.
    for r in range(max(0, fy0), min(h - 1, fy1) + 1):
        for c in range(max(0, fx0), min(w - 1, fx1) + 1):
            if not mask[r, c] or visited[r, c]:
                continue

            stack = [(r, c)]
            visited[r, c] = True
            min_r = max_r = r
            min_c = max_c = c

            while stack:
                rr, cc = stack.pop()

                if rr < min_r:
                    min_r = rr
                if rr > max_r:
                    max_r = rr
                if cc < min_c:
                    min_c = cc
                if cc > max_c:
                    max_c = cc

                for dr, dc in _DIRS:
                    nr = rr + dr
                    nc = cc + dc
                    if 0 <= nr < h and 0 <= nc < w and mask[nr, nc] and not visited[nr, nc]:
                        visited[nr, nc] = True
                        stack.append((nr, nc))

            if min_r >= fy0 and max_r <= fy1 and min_c >= fx0 and max_c <= fx1:
                return False

    return True

import numpy as np

_TARGET_SEQ = (2, 3, 1, 3, 1, 2, 4, 2)
_TOTAL_PROGRESS = len(_TARGET_SEQ)
_INIT_POS = (8, 14)
_SIZE = 5
_STEP = 6


def engine(grid, action, data):
    g = grid.copy()
    H, W = g.shape

    score = 0
    for col in range(W - 1, -1, -1):
        if g[H - 1, col] == 1:
            score += 1
        else:
            break

    pos = None
    if H >= _SIZE and W >= _SIZE:
        for r in range(H - _SIZE + 1):
            for c in range(W - _SIZE + 1):
                b = g[r:r + _SIZE, c:c + _SIZE]
                if (
                    b[2, 2] == 5
                    and bool(np.all(b[0, :] == 9))
                    and bool(np.all(b[1, :] == 9))
                    and bool(np.all(b[3, :] == 9))
                    and bool(np.all(b[4, :] == 9))
                    and b[2, 0] == 9
                    and b[2, 1] == 9
                    and b[2, 3] == 9
                    and b[2, 4] == 9
                ):
                    pos = (r, c)
                    break
            if pos is not None:
                break

    phase1 = False
    if H >= 6 and W >= 8:
        ok = True
        for i in range(3):
            for j in range(3):
                v = g[1 + i, 5 + j]
                if i == 1 and j == 1:
                    if v != 0:
                        ok = False
                        break
                elif v != 9:
                    ok = False
                    break
            if not ok:
                break
        if ok and bool(np.all(g[5, 5:8] == 9)):
            phase1 = True

    if score >= _TOTAL_PROGRESS and pos == _INIT_POS and phase1:
        return g

    if action in (1, 2, 3, 4):
        if pos is not None:
            r, c = pos
            if action == 1:
                nr, nc = r - _STEP, c
            elif action == 2:
                nr, nc = r + _STEP, c
            elif action == 3:
                nr, nc = r, c - _STEP
            else:
                nr, nc = r, c + _STEP

            if nr >= 0 and nc >= 0 and nr + _SIZE < H and nc + _SIZE < W:
                dest = g[nr:nr + _SIZE, nc:nc + _SIZE]
                if bool(np.all(dest == 5)):
                    for i in range(_SIZE):
                        for j in range(_SIZE):
                            if i == 2 and j == 2:
                                continue
                            g[r + i, c + j] = 5
                    for i in range(_SIZE):
                        for j in range(_SIZE):
                            if i == 2 and j == 2:
                                continue
                            g[nr + i, nc + j] = 9

        if score < _TOTAL_PROGRESS and action == _TARGET_SEQ[score]:
            col = W - 1 - score
            if 0 <= col < W:
                g[H - 1, col] = 1

    elif action == 5:
        if H >= 6 and W >= 8 and bool(np.all(g[1:4, 5:8] == 1)):
            for i in range(3):
                for j in range(3):
                    if i == 1 and j == 1:
                        continue
                    g[1 + i, 1 + j] = 2
            g[5, 1:4] = 0

            for i in range(3):
                for j in range(3):
                    if i == 1 and j == 1:
                        continue
                    g[1 + i, 5 + j] = 9
            g[2, 6] = 0
            g[5, 5:8] = 9

    return g


def is_level_complete(grid):
