                    and bool(np.all(b[3, :] == 9))
                    and bool(np.all(b[4, :] == 9))
                    and b[2, 0] == 9
                    and b[2, 1] == 9
                    and b[2, 3] == 9
                    and b[2, 4] == 9
                ):
                    pos = (r, c)
                    break
            if pos is not None:
                break

    if pos != _INIT_POS:
        return False

    phase1 = False
    if H >= 6 and W >= 8:
        ok = True
        for i in range(3):
            for j in range(3):
                v = g[1 + i, 5 + j]
                if i == 1 and j == 1:
                    if v != 0:
                        ok = False
                        break
                elif v != 9:
                    ok = False
                    break
            if not ok:
                break
        if ok and bool(np.all(g[5, 5:8] == 9)):
            phase1 = True

    return phase1

import numpy as np


def engine(grid, action, data):
    g = np.asarray(grid).copy()
    H, W = g.shape

    # Current contiguous zero-progress on the top row (right-to-left)
    # and bottom row (left-to-right).
    kt = 0
    while kt < W and g[0, W - 1 - kt] == 0:
        kt += 1
    kb = 0
    while kb < W and g[H - 1, kb] == 0:
        kb += 1
    k = min(kt, kb)

    hit_object = False

    # Directional actions move the 5x5 color-10 blocks by one 5-cell step.
    if action in (1, 2, 3, 4):
        blocks = []
        for r in range(4, H - 4, 5):
            for c in range(4, W - 4, 5):
                if np.all(g[r:r + 5, c:c + 5] == 10):
                    blocks.append((r, c, r + 4, c + 4))

        valid_indices = []
        new_boxes = {}

        for i, (r0, c0, r1, c1) in enumerate(blocks):
            cx = (c0 + c1) // 2
            dx = 0
            dy = 0

            if action == 1:
                dy = -5
            elif action == 2:
                dy = 5
            elif action == 3:
                # Mirrored horizontal "left": away from vertical center.
                if cx < W / 2.0:
                    dx = -5
                elif cx > W / 2.0:
                    dx = 5
            elif action == 4:
                # Mirrored horizontal "right": toward vertical center.
                if cx < W / 2.0:
                    dx = 5
                elif cx > W / 2.0:
                    dx = -5

            if dx == 0 and dy == 0:
                continue

            nr0 = r0 + dy
            nc0 = c0 + dx
            nr1 = r1 + dy
            nc1 = c1 + dx

            if nr0 < 0 or nc0 < 0 or nr1 >= H or nc1 >= W:
                continue

            # Destination must be clear floor color 5 in the current grid.
            if not np.all(g[nr0:nr1 + 1, nc0:nc1 + 1] == 5):
                continue

            valid_indices.append(i)
            new_boxes[i] = (nr0, nc0, nr1, nc1)

        keep = [True] * len(valid_indices)
        for a in range(len(valid_indices)):
            for b in range(a + 1, len(valid_indices)):
                ia = valid_indices[a]
                ib = valid_indices[b]
                ar0, ac0, ar1, ac1 = new_boxes[ia]
                br0, bc0, br1, bc1 = new_boxes[ib]
                if not (ar1 < br0 or br1 < ar0 or ac1 < bc0 or bc1 < ac0):
                    keep[a] = False
                    keep[b] = False

        final_moves = [valid_indices[idx] for idx in range(len(valid_indices)) if keep[idx]]

        if final_moves:
            out = g.copy()
            for i in final_moves:
                r0, c0, r1, c1 = blocks[i]
                out[r0:r1 + 1, c0:c1 + 1] = 5
            for i in final_moves:
                nr0, nc0, nr1, nc1 = new_boxes[i]
                out[nr0:nr1 + 1, nc0:nc1 + 1] = 10
            g = out

    # Click action: clicking a color-10 object registers a hit.
    elif action == 6:
        if isinstance(data, dict):
            try:
                x = int(round(float(data.get("x", -1))))
                y = int(round(float(data.get("y", -1))))
            except Exception:
                x = -1
                y = -1
            if 0 <= y < H and 0 <= x < W and g[y, x] == 10:
                hit_object = True

    # Progress-bar tick rule inferred from the observed transitions.
    tick = False
    if action == 6:
        tick = hit_object
    else:
        if k > 0:
            if action in (1, 3):
                tick = (k % 2) == 1
            elif action in (4, 5):
                tick = (k % 2) == 0
            else:
                tick = False

    if tick:
        if kt < W:
            g[0, W - 1 - kt] = 0
        if kb < W:
            g[H - 1, kb] = 0

    return g


def is_level_complete(grid):
    g = np.asarray(grid)
    H, W = g.shape
    if H == 0 or W == 0:
        return False

    # Completion by fully filling both HUD progress bars with zeros.
    if np.all(g[0] == 0) and np.all(g[-1] == 0):
        return True

    # Also accept a state where all movable color-10 objects are gone.
    if not np.any(g == 10):
        return True

    return False

import numpy as np

SLOTS = ((18, 21), (26, 29), (34, 37), (42, 45))
ZONES = ((21, 24), (27, 30), (33, 36), (39, 42))
ZONE_CENTERS = (22.5, 28.5, 34.5, 40.5)
FALLBACK_TARGETS = (9, 14, 11, 15)


def engine(grid, action, data):
    g = np.array(grid, copy=True)
    if g.shape != (64, 64):
        return g

    if action == 6:
        x = y = None
        if isinstance(data, dict):
            try:
                x = int(data['x'])
                y = int(data['y'])
            except Exception:
                x = y = None

        if x is not None and y is not None:
            # Click on a bottom tray slot: toggle its selection frame.
            sidx = -1
            if 56 <= y <= 61:
                for i in range(4):
                    L, R = SLOTS[i]
                    if L - 1 <= x <= R + 1:
                        sidx = i
                        break

            if sidx != -1:
                sel = -1
                for i in range(4):
                    L, R = SLOTS[i]
                    if np.all(g[56, L - 1:R + 2] == 0):
                        ok = True
                        for r in range(57, 61):
                            if g[r, L - 1] != 0 or g[r, R + 1] != 0:
                                ok = False
                                break
                        if ok and np.all(g[61, L - 1:R + 2] == 0):
                            sel = i
                            break

                if sel == sidx:
                    L, R = SLOTS[sidx]
                    g[56, L - 1:R + 2] = 4
                    for r in range(57, 61):
                        g[r, L - 1] = 4
                        g[r, R + 1] = 4
                    g[61, L - 1:R + 2] = 4
                else:
                    if sel != -1:
                        L, R = SLOTS[sel]
                        g[56, L - 1:R + 2] = 4
                        for r in range(57, 61):
                            g[r, L - 1] = 4
                            g[r, R + 1] = 4
                        g[61, L - 1:R + 2] = 4

                    L, R = SLOTS[sidx]
                    g[56, L - 1:R + 2] = 0
                    for r in range(57, 61):
                        g[r, L - 1] = 0
                        g[r, R + 1] = 0
                    g[61, L - 1:R + 2] = 0

                return g

            # Click on the central work area while a slot is selected:
            # swap the selected bottom 4x4 tile with the clicked central 4x4 zone.
            zidx = -1
            if 28 <= y <= 31 and 19 <= x <= 44:
                best = 0
                bestdist = abs(x - ZONE_CENTERS[0])
                for i in range(1, 4):
                    d = abs(x - ZONE_CENTERS[i])
                    if d < bestdist:
                        bestdist = d
                        best = i
                zidx = best

            if zidx != -1:
                sel = -1
                for i in range(4):
                    L, R = SLOTS[i]
                    if np.all(g[56, L - 1:R + 2] == 0):
                        ok = True
                        for r in range(57, 61):
                            if g[r, L - 1] != 0 or g[r, R + 1] != 0:
                                ok = False
                                break
                        if ok and np.all(g[61, L - 1:R + 2] == 0):
                            sel = i
                            break

                if sel != -1:
                    L, R = SLOTS[sel]
                    ZL, ZR = ZONES[zidx]

                    old_slot = g[57:61, L:R + 1].copy()
                    old_zone = g[28:32, ZL:ZR + 1].copy()

                    # Clear top and side selection cells; leave the bottom row as observed.
                    g[56, L - 1:R + 2] = 4
                    for r in range(57, 61):
                        g[r, L - 1] = 4
                        g[r, R + 1] = 4

                    g[57:61, L:R + 1] = old_zone
                    g[28:32, ZL:ZR + 1] = old_slot

                    # Advance the right-to-left progress marker on row 53.
                    for c in range(63, -1, -1):
                        if g[53, c] != 3:
                            g[53, c] = 3
                            break

                return g

        return g

    if action == 5:
        sel = -1
        for i in range(4):
            L, R = SLOTS[i]
            if np.all(g[56, L - 1:R + 2] == 0):
                ok = True
                for r in range(57, 61):
                    if g[r, L - 1] != 0 or g[r, R + 1] != 0:
                        ok = False
                        break
                if ok and np.all(g[61, L - 1:R + 2] == 0):
                    sel = i
                    break

        if sel != -1:
            L, R = SLOTS[sel]
            g[56, L - 1:R + 2] = 4
            for r in range(57, 61):
                g[r, L - 1] = 4
                g[r, R + 1] = 4
            g[61, L - 1:R + 2] = 4

            for c in range(63, -1, -1):
                if g[53, c] != 3:
                    g[53, c] = 3
                    break

        return g

    return g


def is_level_complete(grid):
    g = np.array(grid, copy=False)
    if g.shape != (64, 64):
        return False

    targets = []
    item_colors = (9, 11, 14, 15)

    # Read the target order from the top reference panel, left to right.
    for r in range(8):
        row = g[r]
        for c in range(64):
            v = int(row[c])
            if v in item_colors and v not in targets:
                targets.append(v)
                if len(targets) == 4:
                    break
        if len(targets) == 4:
            break

    if len(targets) != 4:
        targets = list(FALLBACK_TARGETS)

    # The four central 4x4 zones must contain the corresponding target colors.
    for i in range(4):
        L, R = ZONES[i]
        if not np.all(g[28:32, L:R + 1] == targets[i]):
            return False

    return True

import numpy as np

