_INIT_Y = 15
_INIT_XL = 18
_AXIS_SUM = 54
_MAX_M = 63


def engine(grid, action, data):
    H, W = grid.shape

    m = 0
    if W > 63:
        while m < _MAX_M and m < H and grid[m, 63] == 5:
            m += 1

    mask = (grid == 5)
    if H > 63:
        mask[63, :] = False
    if W > 63:
        mask[:, 63] = False

    ys, xs = np.where(mask)
    if ys.size == 0:
        y = _INIT_Y
        xL = _INIT_XL
    else:
        y = int(ys.min())
        xL = int(xs.min())

    if y < 0:
        y = 0
    elif y > 54:
        y = 54
    y = ((y + 1) // 3) * 3

    if xL < 0:
        xL = 0
    elif xL > 54:
        xL = 54
    xL = ((xL + 1) // 3) * 3

    hist = getattr(engine, "_hist", None)
    if hist is None:
        hist = []
        engine._hist = hist

    cur = getattr(engine, "_cur", None)
    if m == 0 and y == _INIT_Y and xL == _INIT_XL:
        hist.clear()
    elif cur is not None:
        cy, cx, cm = cur
        if cy != y or cx != xL:
            hist.clear()

    new_y, new_xL = y, xL

    if action == 7:
        if hist:
            py, px = hist.pop()
            new_y, new_xL = py, px
        else:
            dy = y - _INIT_Y
            dx = xL - _INIT_XL
            ay = abs(dy)
            ax = abs(dx)
            ny, nx = y, xL

            if ay > ax:
                if dy > 0:
                    ny -= 3
                elif dy < 0:
                    ny += 3
            elif ax > ay:
                if dx > 0:
                    nx -= 3
                elif dx < 0:
                    nx += 3
            elif ay == ax and ay != 0:
                if dy < 0:
                    ny += 3
                else:
                    if dx >= 0:
                        nx -= 3
                    else:
                        nx += 3

            if ny < 0:
                ny = 0
            elif ny > 54:
                ny = 54
            ny = ((ny + 1) // 3) * 3

            if nx < 0:
                nx = 0
            elif nx > 54:
                nx = 54
            nx = ((nx + 1) // 3) * 3

            new_y, new_xL = ny, nx
    else:
        old_y, old_xL = y, xL

        if action == 1:
            y2, x2 = y - 3, xL
        elif action == 2:
            y2, x2 = y + 3, xL
        elif action == 3:
            y2, x2 = y, xL - 3
        elif action == 4:
            y2, x2 = y, xL + 3
        else:
            y2, x2 = y, xL

        if y2 < 0:
            y2 = 0
        elif y2 > 54:
            y2 = 54
        y2 = ((y2 + 1) // 3) * 3

        if x2 < 0:
            x2 = 0
        elif x2 > 54:
            x2 = 54
        x2 = ((x2 + 1) // 3) * 3

        if action in (1, 2, 3, 4) and (y2, x2) != (old_y, old_xL):
            hist.append((old_y, old_xL))

        new_y, new_xL = y2, x2

    nm = m
    if action in (1, 2, 3, 4, 5) and m < _MAX_M:
        nm = m + 1

    G = _BASE.copy()
    xR = _AXIS_SUM - new_xL

    for ry, rx in _R_SOLID:
        r = new_y + ry
        c = xR + rx
        if 0 <= r < 64 and 0 <= c < 64:
            G[r, c] = 4

    for ry, rx in _L_HOLE:
        r = new_y + ry
        c = new_xL + rx
        if 0 <= r < 64 and 0 <= c < 64:
            b = _BASE[r, c]
            if b == 5 or b == 10 or b == 11:
                G[r, c] = b
            else:
                G[r, c] = 0

    for ry, rx in _L_SOLID:
        r = new_y + ry
        c = new_xL + rx
        if 0 <= r < 64 and 0 <= c < 64:
            G[r, c] = 5

    if nm > 0 and W > 63:
        G[:nm, 63] = 5

    engine._cur = (new_y, new_xL, nm)
    return G.astype(grid.dtype, copy=False)


def is_level_complete(grid):
    try:
        for r, c in _TARGET_CELLS:
            if int(grid[r, c]) != 4:
                return False
        return True
    except Exception:
        return False
